import java.io.InputStreamReader;
import java.io.IOException;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.io.BufferedReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.io.Reader;
import java.io.Writer;
import java.io.InputStream;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        FastPrinter out = new FastPrinter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }
}

class TaskC {
    private int shift;
    private int maxn;
    private char[] d;
    private int[][][][] memo;
    private final int INF = Integer.MAX_VALUE;

    public void solve(int testNumber, FastScanner in, FastPrinter out) {
        shift = 15;
        maxn = 60;
        d = ("000" + in.next()).toCharArray();
        int len = d.length;
        memo = new int[len + 1][maxn + 1][maxn + 1][shift * 2 + 1];
        for (int[][][] a : memo) {
            for (int[][] b : a) {
                for (int[] c : b) Arrays.fill(c, -1);
            }
        }
        int ans = dfs(0, maxn, maxn, shift);
        out.println(ans);
    }

    private int dfs(int pos, int plus, int minus, int carry) {
        if (pos == d.length) {
            return (plus == maxn && minus == maxn && carry == shift) ? 0 : INF;
        }
        if (memo[pos][plus][minus][carry] != -1) return memo[pos][plus][minus][carry];
        int best = INF;
        // propagation: consider states with larger plus/minus
        if (plus < maxn) best = Math.min(best, dfs(pos, plus + 1, minus, carry));
        if (minus < maxn) best = Math.min(best, dfs(pos, plus, minus + 1, carry));
        // process current digit at this state
        int digit = d[pos] - '0';
        int realCarry = carry - shift;
        int curN = plus - minus + realCarry;
        int curD = curN % 10;
        if (curD < 0) curD += 10;
        int newCarry = (curN - curD) / 10;
        if (curD == digit) {
            int nextVal = dfs(pos + 1, plus, minus, newCarry + shift);
            if (nextVal != INF) {
                best = Math.min(best, plus + minus + nextVal);
            }
        }
        memo[pos][plus][minus][carry] = best;
        return best;
    }
}

class FastScanner extends BufferedReader {
    public FastScanner(InputStream is) {
        super(new InputStreamReader(is));
    }
    public int read() {
        try {
            int ret = super.read();
            return ret;
        } catch (IOException e) {
            throw new InputMismatchException();
        }
    }
    public String next() {
        StringBuilder sb = new StringBuilder();
        int c = read();
        while (isWhiteSpace(c)) {
            c = read();
        }
        if (c < 0) {
            return null;
        }
        while (c >= 0 && !isWhiteSpace(c)) {
            sb.appendCodePoint(c);
            c = read();
        }
        return sb.toString();
    }
    static boolean isWhiteSpace(int c) {
        return c >= 0 && c <= 32;
    }
    public String readLine() {
        try {
            return super.readLine();
        } catch (IOException e) {
            return null;
        }
    }
}

class FastPrinter extends PrintWriter {
    public FastPrinter(OutputStream out) {
        super(out);
    }
    public FastPrinter(Writer out) {
        super(out);
    }
}
